import time, os, sys, traceback
from pymilvus import MilvusClient
c = MilvusClient(uri="http://localhost:19530")
cols = c.list_collections(); print("collections:", cols)
coll = None
for name in cols:
    try:
        st = c.get_collection_stats(name); print(" ", name, st)
        if st.get("row_count",0) > 1000: coll = name
    except Exception as e: print(" stats err", name, e)
print("using", coll)
t=time.time()
try:
    rows = c.query(coll, filter="chunk_hash != \"\"", output_fields=["source"], limit=16384)
    print("query sources ok: %d rows in %.1fs" % (len(rows), time.time()-t))
except Exception as e: print("query err %.1fs %s" % (time.time()-t, e))
srcs = set()
try:
    it = c.query_iterator(coll, filter="chunk_hash != \"\"", output_fields=["source"], batch_size=4000)
    while True:
        b = it.next()
        if not b: break
        srcs.update(r["source"] for r in b)
    it.close()
except Exception as e: print("iter err", e)
print("distinct sources indexed:", len(srcs))
home = os.path.expanduser("~")
for d in [r".claude\global-memory\transcripts", r".claude\claude-memory-compiler\daily", r"Desktop\SecondBrain\Inbox\meetings"]:
    root = os.path.join(home, d); disk=[]
    for dp, dn, fn in os.walk(root):
        dn[:] = [x for x in dn if not x.startswith(".")]
        for f in fn:
            if f.lower().endswith(".md") and not f.startswith("."): disk.append(os.path.join(dp,f))
    missing = [p for p in disk if p not in srcs]
    missing.sort(key=lambda p: os.path.getmtime(p))
    indexed = [p for p in disk if p in srcs]
    newest_idx = max((os.path.getmtime(p) for p in indexed), default=0)
    print("%s: %d on disk, %d not indexed; newest indexed mtime=%s; oldest missing=%s" % (d, len(disk), len(missing), time.strftime("%Y-%m-%d %H:%M", time.localtime(newest_idx)) if newest_idx else "-", (os.path.basename(missing[0])+" "+time.strftime("%m-%d %H:%M", time.localtime(os.path.getmtime(missing[0])))) if missing else "-"))
    if missing: print("   newest missing:", os.path.basename(missing[-1]), time.strftime("%m-%d %H:%M", time.localtime(os.path.getmtime(missing[-1]))))
print("== WRITE PROBE 1: no-match delete on real collection, timeout=30")
t=time.time()
try:
    r = c.delete(coll, filter="chunk_hash == \"__diag_no_such_hash__\"", timeout=30); print("delete ok %.1fs %s" % (time.time()-t, r))
except Exception as e: print("delete FAILED %.1fs: %s" % (time.time()-t, str(e)[:300]))
print("== WRITE PROBE 2: insert into throwaway collection, timeout=30")
tmp = "diag_tmp_%d" % os.getpid()
t=time.time()
try:
    c.create_collection(tmp, dimension=4, timeout=30); print("create ok %.1fs" % (time.time()-t))
    t=time.time(); r = c.insert(tmp, [{"id": 1, "vector": [0.1,0.2,0.3,0.4]}], timeout=30); print("insert ok %.1fs %s" % (time.time()-t, r))
except Exception as e: print("insert/create FAILED %.1fs: %s" % (time.time()-t, str(e)[:300]))
finally:
    try: c.drop_collection(tmp, timeout=30); print("dropped", tmp)
    except Exception as e: print("drop err", str(e)[:200])
EOF
